changeSet.sql:
ALTER TABLE questionnaire_field DROP CONSTRAINT ck_questionnaire_field_type;
ALTER TABLE questionnaire_field
    ADD CONSTRAINT ck_questionnaire_field_type CHECK (type IN ('CHECKBOX', 'TEXT', 'SECTION'))

ALTER TABLE drawing_template
    ADD CONSTRAINT ck_drawing_template_archived_at CHECK (archived = (archived_at IS NOT NULL));
CREATE UNIQUE INDEX uq_drawing_template_name ON drawing_template (lower(name))

ALTER TABLE drawing_sheet
    ADD CONSTRAINT ck_drawing_sheet_status CHECK (status IN ('OPEN', 'CLOSED'));
CREATE UNIQUE INDEX uq_drawing_sheet_open_card_template ON drawing_sheet (card_id, template_id) WHERE status = 'OPEN'

ALTER TABLE public.roles DROP CONSTRAINT IF EXISTS roles_name_check;
ALTER TABLE public.roles ADD CONSTRAINT roles_name_check
    CHECK (name IN ('ROLE_ADMIN', 'ROLE_MASTER', 'ROLE_USER'));
INSERT INTO public.roles (name)
SELECT 'ROLE_MASTER'
WHERE NOT EXISTS (SELECT 1 FROM public.roles WHERE name = 'ROLE_MASTER');
